#include "ZeroHourData/ScienceLedgerCodec.hpp"
#include <limits>
#include "errno.hpp"
namespace zero_hour { namespace { constexpr cnc::Size H=8U,R=8U; void w(std::vector<uint8_t>&b,uint64_t v){for(uint32_t s=0;s<64U;s+=8U)b.push_back(static_cast<uint8_t>((v>>s)&255U));} uint64_t r(const uint8_t*p){uint64_t v=0;for(uint32_t s=0;s<64U;s+=8U)v|=static_cast<uint64_t>(p[s/8U])<<s;return v;} bool sz(cnc::Size n,cnc::Size*o)noexcept{if(!o||n>ScienceLedgerCodec::max_entries||n>(std::numeric_limits<cnc::Size>::max()-H)/R)return false;*o=H+n*R;return true;} }}
namespace zero_hour { cnc::Error ScienceLedgerCodec::encode(const ScienceLedger::Snapshot&s,std::vector<uint8_t>*o)noexcept{if(!o)return FT_ERR_INVALID_POINTER;cnc::Size n=static_cast<cnc::Size>(s.purchased.size()),z;if(s.schema_version!=1U||!sz(n,&z))return FT_ERR_INVALID_ARGUMENT;try{o->clear();o->reserve(z);o->push_back(1U);o->push_back(0U);o->push_back(0U);o->push_back(0U);for(uint32_t i=0;i<4U;++i)o->push_back(static_cast<uint8_t>((static_cast<uint32_t>(n)>>(i*8U))&255U));for(auto id:s.purchased){if(id.value==0U){o->clear();return FT_ERR_INVALID_ARGUMENT;}w(*o,id.value);}}catch(...){o->clear();return FT_ERR_NO_MEMORY;}return FT_ERR_SUCCESS;} cnc::Error ScienceLedgerCodec::decode(const uint8_t*p,cnc::Size n,ScienceLedger::Snapshot*o)noexcept{if(!p||!o)return FT_ERR_INVALID_POINTER;if(n<H)return FT_ERR_INVALID_ARGUMENT;uint32_t c=static_cast<uint32_t>(p[4U])|(static_cast<uint32_t>(p[5U])<<8U)|(static_cast<uint32_t>(p[6U])<<16U)|(static_cast<uint32_t>(p[7U])<<24U);cnc::Size z;if(p[0]!=1U||!sz(c,&z)||z!=n)return FT_ERR_CONFIGURATION;ScienceLedger::Snapshot d;try{d.purchased.reserve(c);for(uint32_t i=0;i<c;++i){cnc::DefinitionId id{r(p+H+static_cast<cnc::Size>(i)*R)};if(id.value==0U||(i&&d.purchased.back().value>=id.value))return FT_ERR_CONFIGURATION;d.purchased.push_back(id);}}catch(...){return FT_ERR_NO_MEMORY;}o->schema_version=1U;o->purchased.swap(d.purchased);return FT_ERR_SUCCESS;} }
